import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { useMediaQuery } from "@/registry/erbium/hooks/use-media-query";
export default function Demo() {
  const reducedMotion = useMediaQuery("(prefers-reduced-motion: reduce)", {});
  return (
    <p aria-live="polite">
      Reduced motion: {reducedMotion ? "enabled" : "disabled"}. Change your system preference to
      update.
    </p>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/use-media-query-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  parameters: {
    layout: "centered",
    docs: { description: { component: "Subscribes to a CSS media query and updates when its match changes. This example tracks your system reduced motion preference.\n\nImport `useMediaQuery` from `@/registry/erbium/hooks/use-media-query`." } },
  },
} satisfies Meta;

export default { ...meta, title: "Hooks/Use Media Query",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import Demo from "../examples/use-media-query-demo";

const Example = () => <Demo />;

export default Example;
